static void cs_fields(const char* edge,const char* name,uint8_t* base,uint32_t address){
 if(address!=0xFFCAB000u||!av2_diag_trace_window())return;
 auto* host=rex::memory::GuestPtr(base,address);int32_t lock;std::memcpy(&lock,host+0x10,4);
 const auto recursion=rex::memory::load_and_swap<uint32_t>(host+0x14);
 const auto owner=rex::memory::load_and_swap<uint32_t>(host+0x18);
 av2_boot_log("critical-section","%s %s guest=%08x host=%p owner=%08x lock=%d recursion=%u",edge,name,address,host,owner,lock,recursion);
}
